// Pull tort + state off the inbound event payload so the next HTTP
// node can pass them as query params. Both fields are required for a
// proper routing decision — refuse to assign blindly if either is
// missing, that's what the human review queue is for.
const lead = $json.lead || $json.payload?.lead || $json.payload || {};
const tort = lead.tort_type;
const state = (lead.state || '').toUpperCase();
if (!tort || !state) {
  throw new Error(`Cannot route lead ${lead.id}: missing tort_type or state`);
}
return [{ json: { lead_id: lead.id, tort, state } }];

// Server already filtered by tort + state and ordered by lowest active
// case count (sort=load_asc). We just take [0] — the most-available
// qualified paralegal. Throw on empty so the operator gets a real
// error instead of silently dropping the lead.
const list = Array.isArray($json) ? $json : ($json.paralegals || $json.items || []);
const ctx = $('Extract tort + state').item.json;
if (!Array.isArray(list) || list.length === 0) {
  throw new Error(`No paralegals available for tort='${ctx.tort}' state='${ctx.state}' — escalate to human queue`);
}
const chosen = list[0];
return [{ json: { lead_id: ctx.lead_id, tort: ctx.tort, state: ctx.state, paralegal_id: chosen.id, paralegal_name: chosen.name, paralegal_load: chosen.active_cases } }];
